UPDATE `quest_template_locale` SET `Objectives` = '將恐酒的恐酒帶到奧格瑪附近的啤酒節營地交給泰伯·詐桶。', `Details` = '寇仁·恐酒的屍體緊抓住這個小小的酒桶。這一定是他最惡名昭彰的恐酒!', `VerifiedBuild` = 0 WHERE `locale` = 'zhTW' AND `ID` = 12492;
