DELETE FROM `quest_template_locale` WHERE `ID` IN(7937,7938,7939,7940,7941,7942,7943,7944,7945,7946,7961,7962,7981,8021,8023,8026,8041,8042,8043,8044) AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Objectives`, `Details`, `Objectivetext1`, `Objectivetext2`, `Objectivetext3`, `Objectivetext4`, `VerifiedBuild`) VALUES
(7937,'zhTW','財富等著你……','到艾爾文森林的東谷伐木場去尋找你的財寶吧。','「東谷的財寶正等著你。」$b$b你撫摸著手中的占卜，感到一絲暖意。你緊緊地握住它，眼前浮現出艾爾文森林東谷伐木場的影像。你專注地觀察著，發現馬廄附近有一堆乾草。',NULL,NULL,NULL,NULL,0),
(7938,'zhTW','財富等著你……','到西部荒野的死亡礦坑中去尋找你的財寶吧。','「死亡礦坑中的財寶正等著你。」$b$b你撫摸著手中的占卜，感到一絲暖意。你緊緊地握住它，眼前浮現出位於西部荒野月溪鎮的死亡礦坑的影像。你專注地觀察著，發現蜿蜒的道路盡頭是一道發光的門……通往礦坑中心的門。你穿過大門，不知從哪兒冒出一個奇怪的箱子。',NULL,NULL,NULL,NULL,0),
(7939,'zhTW','更多的緻密砂輪',NULL,NULL,NULL,NULL,NULL,NULL,0),
(7940,'zhTW','1200張獎券 - 暗月寶珠',NULL,NULL,NULL,NULL,NULL,NULL,0),
(7941,'zhTW','更多的護甲片',NULL,NULL,NULL,NULL,NULL,NULL,0),
(7942,'zhTW','更多的瑟銀零件',NULL,NULL,NULL,NULL,NULL,NULL,0),
(7943,'zhTW','更多蝙蝠眼',NULL,NULL,NULL,NULL,NULL,NULL,0),
(7944,'zhTW','財富等著你……','到貧瘠之地的哀嚎洞穴中去尋找你的財寶吧。','「哀嚎洞穴中的財寶正等著你。」$b$b你撫摸著手中的占卜，感到一絲暖意。你緊緊地握住它，眼前浮現出了位於貧瘠之地十字路口西南方的一處洞穴的影像。你專注地觀察著，發現蜿蜒的道路盡頭是一道發光的門……通往洞穴中心的門。你穿過大門，不知從哪兒冒出了一個奇怪的箱子。',NULL,NULL,NULL,NULL,0),
(7945,'zhTW','財富等著你……','到莫高雷的白鬃石去尋找你的財寶吧。','「白鬃石外的財寶正等著你。」$b$b你撫摸著手中的占卜，感到一絲暖意。你緊緊地握住它，眼前浮現出莫高雷白鬃石的影像。你專注地觀察著，發現洞穴入口附近有一塊樹樁。',NULL,NULL,NULL,NULL,0),
(7946,'zhTW','啾啾的蛋',NULL,NULL,NULL,NULL,NULL,NULL,0),
(7961,'zhTW',NULL,'Kill 5 rabbits and return to Jon LeCraft by the forge on Designer Island.',NULL,NULL,NULL,NULL,NULL,0),
(7962,'zhTW','兔皮','帶3張狡猾的兔子的皮給喬恩·勒克夫特。','我要狡猾的兔子的皮。從狡猾的兔子身上取回來給我。$b$b這很重要！',NULL,NULL,NULL,NULL,0),
